    marks = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                marks[c-r] = grid[r][c]

    # Find the smallest diagonal period compatible with every observed mark.
    period = None
    for p in range(1, h + w + 1):
        if all((a-b) % p != 0 or marks[a] == marks[b]
               for a in marks for b in marks):
            period = p
            break

    pattern = {}
    for d, color in marks.items():
        pattern[d % period] = color

    # Fill the unobserved phases by extending the ordered color cycle between
    # the marked phases. The diagonal marks encode the cycle's phase/colors.
    known = sorted(pattern)
    for x in range(period):
        if x not in pattern:
            left = max((k for k in known if k < x), default=None)
            right = min((k for k in known if k > x), default=None)
            if left is None:
                left = known[-1] - period
            if right is None:
                right = known[0] + period
            pattern[x] = pattern[left % period] if x-left <= right-x else pattern[right % period]

    return [[pattern[(c-r) % period] for c in range(w)] for r in range(h)]
